    'Food Security in India',
    'pds_subsidy_calculation_mixed',
    'hard',
    'A family of 5 members receives their NFSA entitlement of 5 kg of food grains per person per month. The entitlement consists of 60% wheat and 40% rice by weight. The market price of wheat is Rs. 32/kg and rice is Rs. 28/kg. The subsidized price under NFSA is Rs. 3/kg for wheat and Rs. 2/kg for rice. What is the total monthly subsidy received by the family?',
    '["Rs. 580","Rs. 695","Rs. 750","Rs. 820"]'::jsonb,
    1,
    'Each person gets 3 kg wheat and 2 kg rice. For 5 members, wheat = 15 kg, rice = 10 kg. Subsidy per kg wheat = Rs. 32 - Rs. 3 = Rs. 29; per kg rice = Rs. 28 - Rs. 2 = Rs. 26. Total subsidy = (15 × 29) + (10 × 26) = Rs. 435 + Rs. 260 = Rs. 695.',
    'seed_rbse_commerce_deepen_social_science_9_v1',
    true,
